#!/usr/bin/env python3
"""Generate payload artifacts for a dynamically linked system CPython."""

from __future__ import annotations

import argparse
import hashlib
import importlib.util
import json
import marshal
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys
import sysconfig
import tempfile

from prepare_python_fallback import (
    create_stubs,
    ensure_venv,
    filter_runtime_requirements,
    compile_awscrt_sources,
    generate_autocomplete_index,
    site_packages,
    validate_awscrt_source,
)


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        while chunk := stream.read(1024 * 1024):
            digest.update(chunk)
    return digest.hexdigest()


def run(args: list[str]) -> None:
    try:
        subprocess.run(
            args,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            check=True,
        )
    except subprocess.CalledProcessError as err:
        if err.stdout:
            sys.stdout.buffer.write(err.stdout)
        if err.stderr:
            sys.stderr.buffer.write(err.stderr)
        raise


def compile_runtime(source: Path, destination: Path) -> None:
    code = compile(
        source.read_bytes(),
        f"src/{source.name}",
        "exec",
        dont_inherit=True,
        optimize=2,
    )
    destination.write_bytes(marshal.dumps(code))


def write_glue(
    destination: Path, embedded_payload: bool, bundled_awscrt: bool
) -> None:
    lines = [
        "// Generated by deps/scripts/prepare_system_python.py;",
        "// do not edit.",
        "#include <Python.h>",
        "",
    ]
    if embedded_payload:
        modules = ["_zippy_finder"]
        if bundled_awscrt:
            modules.append("_awscrt")
        lines.extend(f"PyMODINIT_FUNC PyInit_{name}(void);" for name in modules)
        lines.extend(["", "int register_builtin_extensions(void) {"])
        lines.extend(
            f'    if (PyImport_AppendInittab("{name}", PyInit_{name}) != 0) '
            "return -1;"
            for name in modules
        )
        lines.extend(["    return 0;", "}"])
    else:
        lines.extend(
            [
                "int register_builtin_extensions(void) {",
                "    return 0;",
                "}",
            ]
        )
    lines.extend(["", "void install_frozen_bootstrap(void) {}", ""])
    destination.write_text("\n".join(lines))


def write_metadata(destination: Path, payload: Path, runtime: Path) -> None:
    metadata = {
        "implementation": sys.implementation.name,
        "cache_tag": sys.implementation.cache_tag,
        "magic_number": importlib.util.MAGIC_NUMBER.hex(),
        "payload_sha256": sha256(payload),
        "runtime_sha256": sha256(runtime),
    }
    destination.write_text(
        json.dumps(metadata, indent=2, sort_keys=True) + "\n"
    )


def rust_string(value: str) -> str:
    """Encode UTF-8 text using Rust string-literal escapes."""
    quoted = json.dumps(value, ensure_ascii=False)
    return re.sub(r"\\u([0-9a-f]{4})", r"\\u{\1}", quoted)


def write_config(
    destination: Path,
    embedded_payload: bool,
    bundled_awscrt: bool,
    platlib: str,
    executable: str,
) -> None:
    magic = int.from_bytes(importlib.util.MAGIC_NUMBER, "little")
    configured_platlib = (
        platlib if embedded_payload and not bundled_awscrt else ""
    )
    embedded = "true" if embedded_payload else "false"
    destination.write_text(
        "// Generated by deps/scripts/prepare_system_python.py.\n"
        "pub const DYNAMIC: bool = true;\n"
        f"pub const EMBEDDED_PAYLOAD: bool = {embedded};\n"
        f"pub const EXECUTABLE: &str = {rust_string(executable)};\n"
        f"pub const PLATLIB: &str = {rust_string(configured_platlib)};\n"
        f"pub const BYTECODE_MAGIC: u32 = {magic};\n"
    )


def validate_service_name(service: str) -> None:
    if re.fullmatch(r"[a-z0-9-]+", service) is None:
        raise SystemExit(f"invalid native service name: {service!r}")


def collect_native_service_models(
    aws_cli_source: Path,
    services: list[str],
) -> list[Path]:
    if not services:
        raise SystemExit("system payload requires at least one native service")

    data_root = aws_cli_source / "awscli" / "botocore" / "data"
    if not data_root.is_dir():
        message = f"missing AWS CLI service model directory: {data_root}"
        raise SystemExit(message)
    resolved_data_root = data_root.resolve(strict=True)
    models: list[Path] = []
    seen_services: set[str] = set()
    for service in services:
        validate_service_name(service)
        if service in seen_services:
            raise SystemExit(f"duplicate native service: {service}")
        seen_services.add(service)

        service_root = data_root / service
        if not service_root.is_dir():
            message = f"missing native service model directory: {service_root}"
            raise SystemExit(message)
        service_models = sorted(
            model
            for pattern in ("*/service-2.json", "*/endpoint-rule-set-1.json")
            for model in service_root.glob(pattern)
            if model.is_file()
        )
        if not any(model.name == "service-2.json" for model in service_models):
            message = (
                f"no service-2.json model found for native service: {service}"
            )
            raise SystemExit(message)
        if not any(
            model.name == "endpoint-rule-set-1.json"
            for model in service_models
        ):
            message = (
                "no endpoint-rule-set-1.json model found for native service: "
                f"{service}"
            )
            raise SystemExit(message)

        for model in service_models:
            try:
                model.resolve(strict=True).relative_to(resolved_data_root)
            except ValueError as err:
                message = (
                    "native service model resolves outside AWS CLI source: "
                    f"{model}"
                )
                raise SystemExit(message) from err
            models.append(model)
    partitions = data_root / "partitions.json"
    if not partitions.is_file():
        raise SystemExit(f"missing endpoint partitions resource: {partitions}")
    models.append(partitions)
    return models


def pack_native_service_models(
    system_python: Path,
    pack_tool: Path,
    blob: Path,
    aws_cli_source: Path,
    services: list[str],
) -> None:
    models = collect_native_service_models(aws_cli_source, services)
    with tempfile.TemporaryDirectory(
        prefix="aws-native-models-"
    ) as staging_text:
        staging = Path(staging_text)
        for model in models:
            relative = model.relative_to(aws_cli_source)
            destination = staging / relative
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(model, destination)
        # The trailing colon spells out the empty module prefix: pack.py
        # splits a spec at its last colon, so a bare path is ambiguous.
        run([str(system_python), str(pack_tool), str(blob), f"{staging}:"])


def pack_embedded_payload(
    system_python: Path,
    cache_dir: Path,
    pack_tool: Path,
    gen_ac_index: Path,
    requirements: Path,
    blob: Path,
    aws_cli_source: Path,
    awscrt_source: Path | None,
    platlib: Path,
) -> None:
    stubs = cache_dir / "system-stubs"
    create_stubs(stubs, "x86_64-linux-gnu")
    # The system build is the deliberately non-hermetic one: the selected
    # interpreter, its site-packages, and the caller's PYTHONPATH are the
    # point, so the venv is built in the caller's environment.
    env = dict(os.environ)
    venv_python = ensure_venv(
        system_python,
        cache_dir / "system",
        filter_runtime_requirements(
            requirements, cache_dir / "system-runtime-requirements.txt"
        ),
        stubs,
        env,
    )
    # Without a bundled awscrt, the interpreter's platlib supplies it.
    autocomplete_index = cache_dir / "system-autocomplete-index"
    generate_autocomplete_index(
        venv_python,
        gen_ac_index,
        aws_cli_source,
        platlib if awscrt_source is None else awscrt_source,
        autocomplete_index,
        env,
    )
    specs = [
        f"{stubs}:",
        f"{aws_cli_source / 'awscli'}:awscli",
        f"{autocomplete_index}:",
        f"{site_packages(venv_python, env)}:",
    ]
    if awscrt_source is not None:
        specs.append(f"{awscrt_source / 'awscrt'}:awscrt")
    run([str(system_python), str(pack_tool), str(blob), *specs])


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--payload-mode", choices=("embedded", "system"), required=True
    )
    parser.add_argument("--cache-dir", type=Path, required=True)
    parser.add_argument("--aws-cli-digest", type=Path, required=True)
    parser.add_argument("--aws-cli-source", type=Path, required=True)
    parser.add_argument("--pack-tool", type=Path, required=True)
    parser.add_argument("--gen-ac-index", type=Path)
    parser.add_argument("--requirements", type=Path)
    parser.add_argument("--awscrt-source", type=Path)
    parser.add_argument("--awscrt-version")
    parser.add_argument("--native-service", action="append", default=[])
    parser.add_argument("--runtime-source", type=Path, required=True)
    parser.add_argument("--inittab", type=Path, required=True)
    parser.add_argument("--blob", type=Path, required=True)
    parser.add_argument("--runtime-bytecode", type=Path, required=True)
    parser.add_argument("--metadata", type=Path, required=True)
    parser.add_argument("--python-config", type=Path, required=True)
    # Included in the build-step cache key. The running interpreter is
    # still authoritative; this argument makes a bytecode-version change
    # invalidate a cached generation step even when the executable path stays
    # the same.
    parser.add_argument("--expected-magic", required=True)
    parser.add_argument("--platlib", required=True)
    parser.add_argument("--cc", required=True)
    parser.add_argument("--ar", required=True)
    parser.add_argument("--crt-include", type=Path, required=True)
    parser.add_argument("--target-triple", required=True)
    parser.add_argument("--object-file", type=Path, required=True)
    args = parser.parse_args()

    for output in (
        args.inittab,
        args.blob,
        args.runtime_bytecode,
        args.metadata,
        args.python_config,
    ):
        output.parent.mkdir(parents=True, exist_ok=True)

    embedded = args.payload_mode == "embedded"
    actual_magic = int.from_bytes(importlib.util.MAGIC_NUMBER, "little")
    if str(actual_magic) != args.expected_magic:
        raise SystemExit(
            "selected Python magic changed during configuration: "
            f"expected {args.expected_magic}, found {actual_magic}"
        )
    actual_platlib = sysconfig.get_path("platlib")
    if actual_platlib != args.platlib:
        raise SystemExit(
            "selected Python platlib changed during configuration: "
            f"expected {args.platlib}, found {actual_platlib}"
        )
    aws_cli_source = args.aws_cli_source.resolve(strict=True)
    if not (aws_cli_source / "awscli" / "__init__.py").is_file():
        parser.error("missing tracked AWS CLI package")
    system_python = Path(sys.executable)
    awscrt_source = None
    if args.awscrt_source is not None:
        if not embedded:
            parser.error("--awscrt-source requires the embedded payload")
        if args.awscrt_version is None:
            parser.error("--awscrt-source requires --awscrt-version")
        awscrt_source = validate_awscrt_source(
            args.awscrt_source, args.awscrt_version
        )
    if embedded:
        if args.requirements is None:
            parser.error("embedded payload requires --requirements")
        if args.gen_ac_index is None:
            parser.error("embedded payload requires --gen-ac-index")
        pack_embedded_payload(
            system_python,
            args.cache_dir,
            args.pack_tool,
            args.gen_ac_index,
            args.requirements,
            args.blob,
            aws_cli_source,
            awscrt_source,
            Path(actual_platlib),
        )
    else:
        pack_native_service_models(
            system_python,
            args.pack_tool,
            args.blob,
            aws_cli_source,
            args.native_service,
        )
    compile_runtime(args.runtime_source, args.runtime_bytecode)
    bundled_awscrt = awscrt_source is not None
    write_glue(args.inittab, embedded, bundled_awscrt)
    if awscrt_source is not None:
        objects = compile_awscrt_sources(
            args.cc, args.target_triple,
            Path(sysconfig.get_path("include")), args.crt_include,
            awscrt_source, args.cache_dir / "awscrt-objects",
            None, dict(os.environ),
        )
        args.object_file.unlink(missing_ok=True)
        run([args.ar, "crs", str(args.object_file),
             *(str(path) for path in objects)])
    write_metadata(args.metadata, args.blob, args.runtime_bytecode)
    write_config(
        args.python_config,
        embedded,
        bundled_awscrt,
        args.platlib,
        sys.executable,
    )


if __name__ == "__main__":
    main()
